import unittest
from src.formatting import preview
from src.receipt import receipt_reference

class PreviewTests(unittest.TestCase):
    def test_short_input(self):
        self.assertEqual(preview("abc"), "abc")

    def test_preview_limit(self):
        self.assertEqual(preview("abcdefghijkl"), "abcdefgh")

    def test_receipt_reference_preserved(self):
        self.assertEqual(receipt_reference("abcdefghijklmnop"), "abcdefghijkl")

